import { LoginForm } from "@/app/login/LoginForm"
import { HeroSection } from "@/app/login/HeroSection"

export default function LoginPage() {
  return (
    <div className="min-h-screen bg-white">
      {/* Header - Mobile Only */}
      <header className="bg-gray-900 px-6 py-4 lg:hidden">
        <h1 className="text-white text-lg font-semibold" style={{ fontFamily: "Inter" }}>
          Login
        </h1>
      </header>

      {/* Main Container - 720x839 left + 720x839 right */}
      <div className="flex flex-col lg:flex-row min-h-screen">
        {/* Left Side - Login Form Container 720x839 */}
        <div
          className="w-full lg:w-1/2 flex items-center justify-center px-6 py-12 lg:py-0"
          style={{
            gap: "20px",
          }}
        >
          <LoginForm />
        </div>

        {/* Right Side - Hero Section Container 720x839 */}
        <div className="w-full lg:w-1/2">
          <HeroSection />
        </div>
      </div>
    </div>
  )
}