export function HeroSection() {
  return (
    <div
      className="hidden lg:flex flex-col justify-center items-center w-full h-full px-8 py-12"
      style={{
        backgroundColor: "#1C64F2",
        gap: "32px",
      }}
    >
      {/* Content Container - 720x839 with gap: 32 */}
      <div className="max-w-2xl" style={{ gap: "32px" }}>
        {/* Title & Description - 576x168 with gap: 12 */}
        <div style={{ gap: "12px" }}>
          {/* Heading - 576x60 */}
          <h1
            className="text-white"
            style={{
              fontFamily: "Inter",
              fontWeight: 600,
              fontSize: "40px",
              lineHeight: "150%",
              letterSpacing: "0%",
              verticalAlign: "middle",
            }}
          >
            ticktock
          </h1>

          {/* Supporting Text - 576x96 */}
          <p
            className="text-gray-200"
            style={{
              fontFamily: "Inter",
              fontWeight: 400,
              fontSize: "16px",
              lineHeight: "150%",
              letterSpacing: "0%",
            }}
          >
            Introducing ticktock, our cutting-edge timesheet web application designed to revolutionize how you manage
            employee work hours. With ticktock, you can effortlessly track and monitor employee attendance and
            productivity from anywhere, anytime, using any internet-connected device.
          </p>
        </div>
      </div>
    </div>
  )
}